CREATE TABLE public.external_busy_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), practitioner_id uuid NOT NULL REFERENCES public.practitioners(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, provider text NOT NULL DEFAULT 'mock', label text NOT NULL DEFAULT 'Bezet in eKis', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,practitioner_id,starts_at), CHECK(ends_at>starts_at));
GRANT SELECT ON public.external_busy_periods TO authenticated; GRANT ALL ON public.external_busy_periods TO service_role;
ALTER TABLE public.external_busy_periods ENABLE ROW LEVEL SECURITY;
CREATE POLICY busy_staff_read ON public.external_busy_periods FOR SELECT TO authenticated USING (tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('agenda.view'));
CREATE OR REPLACE FUNCTION public.refuse_external_busy_overlap() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IN ('held','booked') AND EXISTS(SELECT 1 FROM public.external_busy_periods b WHERE b.tenant_id=NEW.tenant_id AND b.practitioner_id=NEW.practitioner_id AND b.starts_at<NEW.ends_at AND NEW.starts_at<b.ends_at) THEN RAISE EXCEPTION 'Deze behandelaar is op dit moment bezet in eKis. Kies een ander moment.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER refuse_external_busy BEFORE INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.refuse_external_busy_overlap();
CREATE TABLE public.patient_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), patient_id uuid NOT NULL REFERENCES public.patients(id), kind text NOT NULL, direction text, subject text NOT NULL, body text NOT NULL DEFAULT '', occurred_at timestamptz NOT NULL DEFAULT now(), follow_up text, assigned_to uuid REFERENCES public.profiles(id), due_on date, done boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE ON public.patient_contacts TO authenticated; GRANT ALL ON public.patient_contacts TO service_role;
ALTER TABLE public.patient_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_read ON public.patient_contacts FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.view'));
CREATE POLICY contacts_insert ON public.patient_contacts FOR INSERT TO authenticated WITH CHECK(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.edit'));
CREATE POLICY contacts_update ON public.patient_contacts FOR UPDATE TO authenticated USING(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.edit')) WITH CHECK(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.edit'));
CREATE TRIGGER contacts_touch BEFORE UPDATE ON public.patient_contacts FOR EACH ROW EXECUTE FUNCTION public.touch_updated(); CREATE TRIGGER contacts_tenant BEFORE UPDATE ON public.patient_contacts FOR EACH ROW EXECUTE FUNCTION public.freeze_tenant(); CREATE TRIGGER contacts_audit AFTER INSERT OR UPDATE ON public.patient_contacts FOR EACH ROW EXECUTE FUNCTION public.audit_row_change();
CREATE TABLE public.patient_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), patient_id uuid NOT NULL REFERENCES public.patients(id), kind text NOT NULL, duration_months integer, explanation text NOT NULL DEFAULT '', destination text NOT NULL, practitioner_id uuid REFERENCES public.practitioners(id), status text NOT NULL DEFAULT 'open', status_changed_at timestamptz NOT NULL DEFAULT now(), status_changed_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE ON public.patient_requests TO authenticated; GRANT ALL ON public.patient_requests TO service_role;
ALTER TABLE public.patient_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY requests_read ON public.patient_requests FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.view'));
CREATE POLICY requests_insert ON public.patient_requests FOR INSERT TO authenticated WITH CHECK(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.edit'));
CREATE POLICY requests_update ON public.patient_requests FOR UPDATE TO authenticated USING(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.edit')) WITH CHECK(tenant_id=public.current_tenant() AND public.is_staff() AND public.has_permission('patients.edit'));
CREATE OR REPLACE FUNCTION public.request_status_stamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN NEW.status_changed_at=now(); NEW.status_changed_by=auth.uid(); END IF; RETURN NEW; END $$;
CREATE TRIGGER requests_status BEFORE INSERT OR UPDATE ON public.patient_requests FOR EACH ROW EXECUTE FUNCTION public.request_status_stamp(); CREATE TRIGGER requests_touch BEFORE UPDATE ON public.patient_requests FOR EACH ROW EXECUTE FUNCTION public.touch_updated(); CREATE TRIGGER requests_tenant BEFORE UPDATE ON public.patient_requests FOR EACH ROW EXECUTE FUNCTION public.freeze_tenant(); CREATE TRIGGER requests_audit AFTER INSERT OR UPDATE ON public.patient_requests FOR EACH ROW EXECUTE FUNCTION public.audit_row_change();